<?php
/**
 * WP-CLI commands, so the platform can pair a site through its host (Forge)
 * without anyone opening the WordPress admin.
 *
 * @package Hop_Connector
 */

defined( 'ABSPATH' ) || exit;

/**
 * Pair this site with Hop.
 */
class Hop_Connector_Cli {

	/**
	 * Pair the site with a token generated by Hop.
	 *
	 * A hop2 token carries Hop's public key: the site is paired at once, and
	 * the command line shows nothing that could sign a request. A hop1 token
	 * carries a one-time secret that Hop confirms within 15 minutes and
	 * replaces at once.
	 *
	 * ## OPTIONS
	 *
	 * <token>
	 * : Pairing token, hop2_<key id>_<public key> or hop1_<key id>_<secret>.
	 *
	 * [--force]
	 * : Replace the current pairing if the site is already paired.
	 *
	 * ## EXAMPLES
	 *
	 *     wp hop-connector pair hop2_0123456789abcdef_<64 hex> --force
	 *
	 * @param  array<int, string>    $args        Positional arguments.
	 * @param  array<string, string> $assoc_args  Flags.
	 * @return void
	 */
	public function pair( $args, $assoc_args ) {
		$key = Hop_Connector_Keys::parse_token( $args[0] ?? '' );

		if ( ! $key ) {
			WP_CLI::error( 'Jeton invalide : attendu hop2_<16 hex>_<64 hex> ou hop1_<16 hex>_<64 hex>.' );
		}

		if ( Hop_Connector_Keys::active() && empty( $assoc_args['force'] ) ) {
			WP_CLI::error( 'Ce site est déjà appairé. Ajoutez --force pour le remplacer.' );
		}

		if ( 'public_key' === $key['type'] ) {
			Hop_Connector_Keys::activate( $key['key_id'], array( 'public_key' => $key['public_key'] ) );

			WP_CLI::success( 'Clé publique de Hop enregistrée : le site est appairé.' );

			return;
		}

		Hop_Connector_Keys::store_pending( $key['key_id'], $key['secret'] );

		WP_CLI::success( 'Jeton enregistré : Hop doit le confirmer dans les 15 minutes.' );
	}
}
